def cron_match(expr, dt):
    m, h, dom, mon, dow = expr.split()
    return (field_match(m, dt.minute) and field_match(h, dt.hour) and field_match(dom, dt.day)
            and field_match(mon, dt.month) and field_match(dow, dt.isoweekday() % 7))
